struct MemCard {
    int free;
    bool exists;
    bool changed;
    bool available;
    bool ask_format;
    bool saved_games;
    int status;
};
class SaveLoadFrontEnd;
class NamesMenu : public FEMultiMenu {
    int type;
    bool save;
    vector2d card_center;
    SaveLoadFrontEnd *sl_parent;
    int check_cards_counter;
    int arrow_num;
    int arrow_counter;
    bool empty[15];
    MemCard cards[2];
    stringx blank_name;
    int active_card;
    int adjusted_active_card;
    bool cardSide;
    PanelQuad *box;
    PanelQuad *arrows[2][2];
    PanelQuad *lines[10];
    PanelQuad *top_line;
    PanelQuad *side_line;
    FEMenuEntry *entry[17];
    BoxText *message;
    BoxText *freeSpace;
    bool draw_message;
public:
    virtual ~NamesMenu();
};

NamesMenu::~NamesMenu()
{
    delete message;
    delete freeSpace;
}
